import type { Handle } from '../scene/hit_test';
import type { Vec2 } from '@archeglyph/core/geometry/vec2';
import type { ModalGesture } from '../ui_state/modal_gesture';

export function modalDelta(gesture: ModalGesture): Vec2 {
  if (gesture.direction === undefined) {
    return { x: 0, y: 0 };
  }

  const magnitude: number = gesture.digits === '' ? 0 : Number.parseInt(gesture.digits, 10);
  if (magnitude === 0) {
    return { x: 0, y: 0 };
  }

  switch (gesture.direction) {
    case 'up':
      return { x: 0, y: -magnitude };
    case 'down':
      return { x: 0, y: magnitude };
    case 'left':
      return { x: -magnitude, y: 0 };
    case 'right':
      return { x: magnitude, y: 0 };
  }
}

export function modalHandle(gesture: ModalGesture): Handle | undefined {
  switch (gesture.direction) {
    case 'up':
      return 'n';
    case 'down':
      return 's';
    case 'left':
      return 'w';
    case 'right':
      return 'e';
    default:
      return undefined;
  }
}
